+/// #2243: hold the exact Tcllib file that exposed intermittent extra T100s
+/// for interpreter-bound `$argc` in the memoised top-level taint solve.
+#[test]
+fn compiler_check_memo_matches_uncached_imap4_argc() {
+    use tcl_compiler::compiler_checks::DiagCode;
+
+    let dialect = "tcl8.6";
+    let corpus = std::env::var_os("TCLLIB_2_0_DIR")
+        .map_or_else(|| repo_root().join("tmp/tcllib-2.0"), PathBuf::from);
+    let held = FixedCorpusSource::read(&corpus, &TCLLIB_2_0_IMAP4)
+        .expect("#2243 requires the pinned Tcllib 2.0 IMAP4 input");
+    let src = String::from_utf8(held.bytes().to_vec()).expect("Tcllib IMAP4 source is UTF-8");
+    assert_eq!(src.as_bytes().get(43_921..43_926), Some(&b"$argc"[..]));
+    assert_eq!(src.as_bytes().get(43_960..43_965), Some(&b"$argc"[..]));
+    let events = Arc::new(Mutex::new(Vec::<String>::new()));
+    let event_sink = Arc::clone(&events);
+    let db = TclDatabase::with_event_logger(move |key| {
+        event_sink.lock().unwrap().push(key);
+    });
+    let file = SourceFile::new(&db, src.clone(), dialect.to_owned(), None);
+    let config = default_config(&db);
+    let got = compiler_check_diagnostics_if_available(&db, file, config)
+        .expect("the pinned IMAP4 document must complete the checked provider");
+    let cold_events = std::mem::take(&mut *events.lock().unwrap());
+    let solves = cold_events
+        .iter()
+        .filter(|key| key.contains("proc_taint_solve_for_config"))
+        .count();
+    let lattices = cold_events
+        .iter()
+        .filter(|key| key.contains("function_lattice"))
+        .count();
+    assert_eq!(solves, 1, "the exact document must enter its taint solve");
+    assert!(
+        lattices > 0,
+        "the document must issue per-body lattice work"
+    );
+    let repeated = compiler_check_diagnostics_if_available(&db, file, config)
+        .expect("the same completed provider stays available");
+    assert!(
+        Arc::ptr_eq(&got, &repeated),
+        "the warm report must be reused"
+    );
+    assert!(
+        events.lock().unwrap().is_empty(),
+        "a no-op demand must reuse every memo"
+    );
+    eprintln!("IMAP4 memo activity: cold solves={solves}, lattices={lattices}; warm executions=0");
+    let registry = db.registry(dialect);
+    let want = compiler_check_diagnostics_uncached(&src, registry, dialect, None, None);
+    let got_t100: Vec<_> = got
+        .checks
+        .iter()
+        .filter(|check| check.code == DiagCode::T100)
+        .collect();
+    let want_t100: Vec<_> = want
+        .checks
+        .iter()
+        .filter(|check| check.code == DiagCode::T100)
+        .collect();
+    assert_eq!(got_t100, want_t100, "imap4 T100s diverge");
+    assert!(
+        got_t100.iter().all(|check| check
+            .taint_subject
+            .as_ref()
+            .is_some_and(|subject| subject.variable() != "argc")),
+        "interpreter-bound argc must stay clean: {got_t100:?}"
+    );
+    assert_eq!(got.checks, want.checks, "imap4 checks diverge");
+    assert_eq!(
+        got.optimisations, want.optimisations,
+        "imap4 optimisations diverge"
+    );
+    assert_eq!(
+        got.taint_replays, want.taint_replays,
+        "imap4 replays diverge"
+    );
+}
